from collections import deque
h,w=len(g),len(g[0]); seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if g[r][c]==2 and (r,c) not in seen:
   q=deque([(r,c)]);seen.add((r,c)); comp=[]
   while q:
    x,y=q.popleft();comp.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<h and 0<=b<w and g[a][b]==2 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
   comps.append(comp)
hit=[]
for comp in comps:
 if any(r in (4,11) or c==5 for r,c in comp):
  hit.append((min(r for r,c in comp),max(r for r,c in comp),min(c for r,c in comp),max(c for r,c in comp),len(comp)))
  for r,c in comp:g[r][c]=1
for r in (4,11):g[r]=[1]*w
for r in range(h):g[r][5]=1
print(hit)
for row in g:print(' '.join(map(str,row)))

